DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'upsert_holding_buy' AND p.prosecdef AND coalesce(array_to_string(p.proconfig, ', '), '') LIKE '%search_path=public, pg_temp%' AND pg_get_functiondef(p.oid) LIKE '%auth.uid() IS NULL OR auth.uid() <> p_user_id%') THEN RAISE EXCEPTION 'upsert_holding_buy ownership invariant not verified'; END IF; IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'upsert_holding_sell' AND p.prosecdef AND coalesce(array_to_string(p.proconfig, ', '), '') LIKE '%search_path=public, pg_temp%' AND pg_get_functiondef(p.oid) LIKE '%auth.uid() IS NULL OR auth.uid() <> p_user_id%') THEN RAISE EXCEPTION 'upsert_holding_sell ownership invariant not verified'; END IF; IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'adjust_cash_balance' AND p.prosecdef AND coalesce(array_to_string(p.proconfig, ', '), '') LIKE '%search_path=public, pg_temp%' AND pg_get_functiondef(p.oid) LIKE '%auth.uid() IS NULL OR auth.uid() <> p_user_id%') THEN RAISE EXCEPTION 'adjust_cash_balance ownership invariant not verified'; END IF; END $$;
